={{ (() => {
  const s = $('Set your targets').first().json;
  const list = v => String(v || '').split(',').map(x => x.trim()).filter(Boolean);
  const col = String(s.domainColumn);
  const domains = $json.accounts
    .map(r => String(r[col] ?? '').trim())
    .filter(Boolean)
    .map(d => d.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''));
  return JSON.stringify({
    companies: [...new Set(domains)],
    keywords: list(s.titleKeywords),
    locationFilter: list(s.locations),
    includeDescription: true,
    descriptionFormat: 'markdown',
    incremental: true,
    maxItems: s.maxJobs
  });
})() }}

parameters.jsCode:
const groups = {};
for (const item of $input.all()) {
  const j = item.json;
  const dom = String(j.source_domain || '').toLowerCase();
  if (!dom) continue;
  const g = groups[dom] || (groups[dom] = { domain: dom, company: j.company || dom, roles: [] });
  g.roles.push(j);
}
const out = [];
for (const g of Object.values(groups)) {
  g.roles.sort((a, b) => String(b.posted_at || '').localeCompare(String(a.posted_at || '')));
  const top = g.roles.slice(0, 12);
  const lines = top.map(r => {
    const bits = [r.title];
    if (r.department) bits.push('team: ' + r.department);
    if (r.seniority) bits.push(String(r.seniority).replaceAll('_', ' '));
    if (r.location) bits.push(r.location);
    if (r.posted_at) bits.push('posted ' + String(r.posted_at).slice(0, 10));
    const head = '- ' + bits.join(' | ');
    const body = String(r.description_markdown || r.description_text || '')
      .replace(/[#*>`|]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 700);
    return body ? head + '\n    ' + body : head;
  });
  out.push({ json: {
    domain: g.domain,
    company: g.company,
    openRoles: g.roles.length,
    newRoles: g.roles.filter(r => r.change_status === 'new').length,
    titles: top.map(r => r.title).join('; '),
    departments: [...new Set(g.roles.map(r => r.department).filter(Boolean))].join(', '),
    firstApplyUrl: (top[0] || {}).apply_url || (top[0] || {}).job_url || '',
    postings: lines.join('\n')
  } });
}
return out;

