  + ' \u00b7 signal ' + a['Score'] + '/100\n'
  + '\ud83d\udcc8 ' + esc(a['Signal']) + '\n'
  + (String(a['Evidence'] || '').trim() ? '\ud83d\udcce <i>' + esc(cut(a['Evidence'], 220)) + '</i>\n' : '')
  + '\ud83d\udcbc ' + a['Open roles'] + ' open \u00b7 ' + esc(cut(a['Roles seen'], 120)) + '\n\n'
  + (subject ? '<b>Subject</b>\n' + esc(subject) + '\n\n' : '')
  + '<b>Opener</b>\n<pre>' + esc(body) + '</pre>\n\n'
  + '\u27a1 <a href="' + a['Example posting'] + '">The posting this came from</a>';
})() }}
